(function () {
    'use strict';

    function normalizeValue(value) {
        if (value === null || value === undefined) return '';
        if (Array.isArray(value) || typeof value === 'object') {
            try {
                return JSON.stringify(value);
            } catch (error) {
                return String(value);
            }
        }
        return value;
    }

    function stripHtml(value) {
        value = normalizeValue(value);
        if (typeof value !== 'string' || value.indexOf('<') === -1) return value;

        var container = document.createElement('div');
        container.innerHTML = value;
        return (container.textContent || container.innerText || '').trim();
    }

    function getDataTableExport(tableId) {
        var selector = '#' + tableId;
        if (!window.jQuery || !$.fn.dataTable || !$.fn.dataTable.isDataTable(selector)) {
            return null;
        }

        var table = $(selector).DataTable();
        var columnIndexes = table.columns(':visible').indexes().toArray();
        var rowIndexes = table.rows({ search: 'applied', order: 'applied' }).indexes().toArray();
        var headers = columnIndexes.map(function (columnIndex) {
            return stripHtml(table.column(columnIndex).header().textContent);
        });
        var rows = rowIndexes.map(function (rowIndex) {
            return columnIndexes.map(function (columnIndex) {
                return stripHtml(table.cell(rowIndex, columnIndex).render('display'));
            });
        });

        return { headers: headers, rows: rows };
    }

    function collectExportOptions(exportRoot) {
        var options = {};
        exportRoot.querySelectorAll('[data-export-option]').forEach(function (control) {
            options[control.getAttribute('data-export-option')] = control.value;
        });
        return options;
    }

    function refreshExportOptions(exportRoot) {
        var providerName = exportRoot.getAttribute('data-export-options-provider');
        if (!providerName || typeof window[providerName] !== 'function') return;

        var select = exportRoot.querySelector('[data-export-options]');
        if (!select) return;

        var configuration = window[providerName]();
        if (!configuration || !Array.isArray(configuration.options)) return;

        var previousValue = select.value;
        select.innerHTML = '';
        configuration.options.forEach(function (item) {
            var option = document.createElement('option');
            option.value = String(item.value);
            option.textContent = item.label;
            select.appendChild(option);
        });

        var hasPreviousValue = configuration.options.some(function (item) {
            return String(item.value) === previousValue;
        });
        select.value = hasPreviousValue ? previousValue : String(configuration.selected);
    }

    function getExportData(exportRoot) {
        var providerName = exportRoot.getAttribute('data-export-provider');
        if (providerName && typeof window[providerName] === 'function') {
            return window[providerName](collectExportOptions(exportRoot));
        }
        return getDataTableExport(exportRoot.getAttribute('data-export-table'));
    }

    function protectSpreadsheetFormula(value) {
        if (typeof value === 'string' && /^[=+\-@]/.test(value)) return "'" + value;
        return value;
    }

    function csvCell(value) {
        value = protectSpreadsheetFormula(normalizeValue(value));
        var text = String(value);
        return /[",\r\n]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
    }

    function makeCsv(data) {
        var lines = [data.headers.map(csvCell).join(',')];
        data.rows.forEach(function (row) {
            lines.push(row.map(csvCell).join(','));
        });
        return '\ufeff' + lines.join('\r\n');
    }

    function escapeXml(value) {
        return String(value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&apos;');
    }

    function excelCell(value, isHeader) {
        value = normalizeValue(value);
        var isNumber = !isHeader && typeof value === 'number' && Number.isFinite(value);
        var type = isNumber ? 'Number' : 'String';
        var style = isHeader ? ' ss:StyleID="Header"' : '';
        return '<Cell' + style + '><Data ss:Type="' + type + '">' + escapeXml(value) + '</Data></Cell>';
    }

    function makeExcelXml(data) {
        var headerRow = '<Row>' + data.headers.map(function (header) {
            return excelCell(header, true);
        }).join('') + '</Row>';
        var rows = data.rows.map(function (row) {
            return '<Row>' + row.map(function (value) {
                return excelCell(value, false);
            }).join('') + '</Row>';
        }).join('');

        return '<?xml version="1.0" encoding="UTF-8"?>' +
            '<?mso-application progid="Excel.Sheet"?>' +
            '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" ' +
            'xmlns:o="urn:schemas-microsoft-com:office:office" ' +
            'xmlns:x="urn:schemas-microsoft-com:office:excel" ' +
            'xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">' +
            '<Styles><Style ss:ID="Header"><Font ss:Bold="1"/><Interior ss:Color="#D9EAF7" ss:Pattern="Solid"/></Style></Styles>' +
            '<Worksheet ss:Name="Watch"><Table>' + headerRow + rows + '</Table>' +
            '<WorksheetOptions xmlns="urn:schemas-microsoft-com:office:excel"><DisplayRightToLeft/></WorksheetOptions>' +
            '</Worksheet></Workbook>';
    }

    function download(content, mimeType, fileName) {
        var blob = new Blob([content], { type: mimeType });
        var url = URL.createObjectURL(blob);
        var link = document.createElement('a');
        link.href = url;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(function () { URL.revokeObjectURL(url); }, 0);
    }

    function dateSuffix() {
        var now = new Date();
        return now.getFullYear() + '-' +
            String(now.getMonth() + 1).padStart(2, '0') + '-' +
            String(now.getDate()).padStart(2, '0');
    }

    function closeAllMenus(except) {
        document.querySelectorAll('.watch-export-menu').forEach(function (menu) {
            if (menu !== except) {
                menu.hidden = true;
                var exportRoot = menu.closest('[data-watch-export]');
                var trigger = exportRoot && exportRoot.querySelector('.watch-export-trigger');
                if (trigger) trigger.setAttribute('aria-expanded', 'false');
            }
        });
    }

    function hasExportAccess(exportRoot) {
        if (!exportRoot) return true;
        var access = exportRoot.getAttribute('data-export-access');
        return access == null || access === '' || access === 'true' || Number(access) === 2;
    }

    function showExportAccessMessage(exportRoot) {
        var messageId = exportRoot && exportRoot.getAttribute('data-export-access-message');
        var message = messageId ? document.getElementById(messageId) : null;
        if (!message) {
            alert('Ø®Ø±ÙØ¬Û Ø§Ú©Ø³Ù Ù CSV ÙÛÚÙ ÙØ´ØªØ±Ú©ÛÙ Ø§Ø³Øª.');
            return;
        }
        message.hidden = false;
        message.style.display = '';
        if (message._exportAccessTimer) window.clearTimeout(message._exportAccessTimer);
        message._exportAccessTimer = window.setTimeout(function () {
            message.hidden = true;
        }, 5000);
    }

    document.addEventListener('click', function (event) {
        var trigger = event.target.closest('.watch-export-trigger');
        if (trigger) {
            var triggerRoot = trigger.closest('[data-watch-export]');
			if (triggerRoot && !hasExportAccess(triggerRoot)) {
				event.preventDefault();
				showExportAccessMessage(triggerRoot);
				return;
			}
            var menu = triggerRoot && triggerRoot.querySelector('.watch-export-menu');
            if (!menu) return;

            refreshExportOptions(triggerRoot);
            var shouldOpen = menu.hidden;
            closeAllMenus(menu);
            menu.hidden = !shouldOpen;
            trigger.setAttribute('aria-expanded', String(shouldOpen));
            return;
        }

        var action = event.target.closest('[data-export-format]');
        if (!action) {
            if (event.target.closest('[data-watch-export]')) return;
            closeAllMenus();
            return;
        }

        var exportRoot = action.closest('[data-watch-export]');
        var exportMenu = exportRoot && exportRoot.querySelector('.watch-export-menu');
        var exportTrigger = exportRoot && exportRoot.querySelector('.watch-export-trigger');
        if (!exportRoot) return;
		if (!hasExportAccess(exportRoot)) {
			event.preventDefault();
			if (exportMenu) exportMenu.hidden = true;
			if (exportTrigger) exportTrigger.setAttribute('aria-expanded', 'false');
			showExportAccessMessage(exportRoot);
			return;
		}

        var data = getExportData(exportRoot);
        if (exportMenu) exportMenu.hidden = true;
        if (exportTrigger) exportTrigger.setAttribute('aria-expanded', 'false');

        if (!data || !Array.isArray(data.headers) || !Array.isArray(data.rows) || data.rows.length === 0) {
            alert('Ø¯Ø§Ø¯ÙâØ§Û Ø¨Ø±Ø§Û Ø®Ø±ÙØ¬Û Ú¯Ø±ÙØªÙ ÙØ¬ÙØ¯ ÙØ¯Ø§Ø±Ø¯.');
            return;
        }

        var baseName = exportRoot.getAttribute('data-export-name') || 'watch';
        var format = action.getAttribute('data-export-format');
        if (format === 'csv') {
            download(makeCsv(data), 'text/csv;charset=utf-8', baseName + '-' + dateSuffix() + '.csv');
        } else {
            download(makeExcelXml(data), 'application/vnd.ms-excel;charset=utf-8', baseName + '-' + dateSuffix() + '.xls');
        }
    });

    document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape') closeAllMenus();
    });
}());

